import 'dart:io'; import 'package:postgres/postgres.dart'; import 'package:dotenv/dotenv.dart'; void main() async { var env = DotEnv(includePlatformEnvironment: true)..load(); final dbUrl = env['DATABASE_URL']!; final uri = Uri.parse(dbUrl); final connection = await Connection.open(Endpoint(host: uri.host, port: uri.hasPort ? uri.port : 5432, database: uri.path.replaceAll('/', ''), username: uri.userInfo.split(':')[0], password: uri.userInfo.split(':')[1]), settings: const ConnectionSettings(sslMode: SslMode.require)); try { await connection.execute('SELECT 1 FROM accounts_technician_profile_skills LIMIT 1'); print('SKILLS TABLE OK'); } catch (e) { print('SKILLS TABLE ERROR: \'); } await connection.close(); }
